-- Reverse the final de-tenant migration.

BEGIN;

-- Drop the tenant-less materialized views created by this migration's up.
DROP MATERIALIZED VIEW IF EXISTS public.mv_daily_content_stats CASCADE;
DROP MATERIALIZED VIEW IF EXISTS public.mv_daily_space_stats CASCADE;
DROP MATERIALIZED VIEW IF EXISTS public.mv_revenue_streams CASCADE;
DROP MATERIALIZED VIEW IF EXISTS public.mv_top_content_30d CASCADE;
DROP MATERIALIZED VIEW IF EXISTS public.mv_top_content_7d CASCADE;
DROP MATERIALIZED VIEW IF EXISTS public.mv_top_content_90d CASCADE;
DROP MATERIALIZED VIEW IF EXISTS public.mv_user_engagement_stats CASCADE;

-- Recreate the tenants table.
CREATE TABLE IF NOT EXISTS tenants (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name text NOT NULL,
    slug text NOT NULL,
    domain text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    status text NOT NULL DEFAULT 'active' CHECK (status = ANY (ARRAY['active'::text, 'suspended'::text, 'deleted'::text])),
    deleted_at timestamptz
);
CREATE UNIQUE INDEX IF NOT EXISTS tenants_slug_key ON tenants (slug);
CREATE UNIQUE INDEX IF NOT EXISTS tenants_domain_unique ON tenants (domain);
CREATE INDEX IF NOT EXISTS idx_tenants_status ON tenants (status);
CREATE INDEX IF NOT EXISTS idx_tenants_deleted_at ON tenants (deleted_at) WHERE deleted_at IS NOT NULL;

-- Ensure the default tenant row exists so FK checks pass.
INSERT INTO tenants (id, name, slug, status) VALUES ('00000000-0000-0000-0000-000000000001'::uuid, 'Default', 'default', 'active')
ON CONFLICT (id) DO NOTHING;

